59	    private MvcResult postJson(String url, Map<String, Object> body, String actor, int expectedStatus)
60	            throws Exception {
61	        var request = post(url).contentType(MediaType.APPLICATION_JSON)
62	                .content(objectMapper.writeValueAsString(body));
63	        if (actor != null) {
64	            request = request.header("X-Actor-Id", actor);
65	        }
66	        return mvc.perform(request).andExpect(status().is(expectedStatus)).andReturn();
67	    }
